{"task": "Judge all four claims using only the supplied public source. Do not assume source was executed. Distinguish Add invocations from distinct returned map entries. Return exactly one JSON object with records array. Each record: id,verdict(SUPPORTED/CONTRADICTED/INCONCLUSIVE),reason_en,reason_pt,sources(array of source card IDs). Both reasons must explain the specific branch/map logic in their stated languages. Preserve identifiers. No Markdown.", "source_cards": [{"id": "E02", "path": "promql/estimate.go", "revision": "80cd8d97bdfce88014a652d15723559d00a15902", "source_sha256": "8c2bf58bb82b6301cf4cf6bf9a1a10fab60701102eec16e6ba86cc15167966c7", "first_line": 239, "last_line": 280, "quote": "	for _, sel := range selectors {
		series, sa, err := countSeries(ctx, querier, sel.mint, sel.maxt, sel.matchers)
		annos = annos.Merge(sa)
		if err != nil {
			return CostEstimate{}, annos, err
		}

		estimate.SeriesTouched = addSaturatingInt64(estimate.SeriesTouched, series)

		// Sample the real window within a fixed chunk budget. Completed series
		// constrain extrapolation across gaps; partial series still inform the
		// interval when the window is too large to sample a whole series.
		effInterval := scrapeInterval
		avgPointCost := fallbackAvgPointCost
		var density selectorDensity
		if sampler != nil && series > 0 {
			var sia annotations.Annotations
			density, sia, err = sampleSelectorDensity(ctx, sampler, sel.mint, sel.maxt, sel.matchers)
			annos = annos.Merge(sia)
			if err != nil && !samplingUnsupported(err) {
				return CostEstimate{}, annos, err
			}
			if err == nil {
				var sca annotations.Annotations
				avgPointCost, sca, err = sampleAvgPointCost(ctx, sampler, sel.mint, sel.maxt, series, scrapeInterval, sel.skipHistogramBuckets, sel.matchers)
				annos = annos.Merge(sca)
				if err != nil && !samplingUnsupported(err) {
					return CostEstimate{}, annos, err
				}
			}
			if err != nil {
				// A later opening can see a new unsupported layout. Discard both
				// measurements rather than keeping a partially sampled estimate.
				density = selectorDensity{}
				avgPointCost = fallbackAvgPointCost
				annos.Add(errCostSamplingFallback)
			} else if density.intervalMs > 0 {
				effInterval = time.Duration(density.intervalMs * float64(time.Millisecond))
			}
		} else if series > 0 {
			annos.Add(errCostSamplingFallback)
		}
", "quote_sha256": "9586b12eb7f4abe5365651cb3be13900a5bdfb029a76f8d111b9a6072191ff8e"}, {"id": "E03", "path": "promql/estimate.go", "revision": "80cd8d97bdfce88014a652d15723559d00a15902", "source_sha256": "8c2bf58bb82b6301cf4cf6bf9a1a10fab60701102eec16e6ba86cc15167966c7", "first_line": 282, "last_line": 301, "quote": "		// Estimate samples per series following the engine's incremental reads,
		// then multiply by the series count and scale by the measured per-point
		// cost. All arithmetic saturates to avoid int64 overflow for huge windows
		// with tiny scrape intervals.
		selectorSamples := mulSaturatingInt64(series, samplesPerSeries(sel.isRange, sel.rangeMs, sel.stepMs, effInterval, sel.numSteps))
		if sel.isRange && density.completeSeries > 0 {
			// A range selector cannot consume more points than exist in its
			// storage window. Extrapolate the mean of fully sampled series, not
			// a partial series that happened to exhaust the sampling budget.
			windowSamples := scaleSaturatingInt64(series, float64(density.samples)/float64(density.completeSeries))
			selectorSamples = min(selectorSamples, windowSamples)
		}
		selectorSamples = scaleSaturatingInt64(selectorSamples, avgPointCost)
		estimate.SamplesRead = addSaturatingInt64(estimate.SamplesRead, selectorSamples)
	}

	return estimate, annos, nil
}

var errCostSamplingFallback = errors.New("query cost estimate uses the configured scrape interval and float-sized points because bounded storage sampling is unavailable")
", "quote_sha256": "4c65282813d9735f9730ef947f6fba05db30bbe9ca29f95f144c278ebe7a9139"}, {"id": "E15", "path": "util/annotations/annotations.go", "revision": "80cd8d97bdfce88014a652d15723559d00a15902", "source_sha256": "fff70f37214b1b3447f6f6cbe762f0e84bc7c41c595bb944899df0e3bf458848", "first_line": 26, "last_line": 53, "quote": "// Annotations is a general wrapper for warnings and other information
// that is returned by the query API along with the results.
// Each individual annotation is modeled by a Go error.
// They are deduplicated based on the string returned by error.Error().
// The zero value is usable without further initialization, see New().
type Annotations map[string]error

// New returns new Annotations ready to use. Note that the zero value of
// Annotations is also fully usable, but using this method is often more
// readable.
func New() *Annotations {
	return &Annotations{}
}

// Add adds an annotation (modeled as a Go error) in-place and returns the
// modified Annotations for convenience.
func (a *Annotations) Add(err error) Annotations {
	if *a == nil {
		*a = Annotations{}
	}
	if prevErr, exists := (*a)[err.Error()]; exists {
		if anErr, ok := errors.AsType[annoError](err); ok {
			err = anErr.Merge(prevErr)
		}
	}
	(*a)[err.Error()] = err
	return *a
}
", "quote_sha256": "b86df054fcc598bec332b25cf23f56949b425fbb0deabbf6ec89cdadfa905975"}, {"id": "E16", "path": "util/annotations/annotations.go", "revision": "80cd8d97bdfce88014a652d15723559d00a15902", "source_sha256": "fff70f37214b1b3447f6f6cbe762f0e84bc7c41c595bb944899df0e3bf458848", "first_line": 55, "last_line": 73, "quote": "// Merge adds the contents of the second set of Annotations to the first, modifying
// the first in-place, and returns the merged first Annotations for convenience.
func (a *Annotations) Merge(aa Annotations) Annotations {
	if *a == nil {
		if aa == nil {
			return nil
		}
		*a = Annotations{}
	}
	for key, val := range aa {
		if prevVal, exists := (*a)[key]; exists {
			if anErr, ok := errors.AsType[annoError](val); ok {
				val = anErr.Merge(prevVal)
			}
		}
		(*a)[key] = val
	}
	return *a
}
